INSERT INTO biblioteca_jogos.biblioteca (id_usuario, id_jogo, data_aquisicao, horas_jogadas)
SELECT p.id_usuario, pr.id_jogo,
       now() - (pr.dias_atras || ' days')::interval,
       pr.horas_jogadas
FROM pares pr
JOIN pool_usuarios p ON p.rn = pr.rn
ON CONFLICT (id_usuario, id_jogo) DO NOTHING;

